 'use strict';
function keyboardPanel(){if(tradeOverlay)return tradeOverlay;if(!$('modal').hidden)return $('modal');if(!$('characterOverlay').hidden)return $('characterOverlay');if(screen!=='play')return document.querySelector('.screen:not([hidden])');return null}
window.addEventListener('keydown',e=>{const root=keyboardPanel();if(!root)return;const controls=[...root.querySelectorAll('button,input,select')].filter(el=>!el.disabled&&el.getClientRects().length&&getComputedStyle(el).visibility!=='hidden');if(!controls.length)return;const active=document.activeElement;if(e.code==='Escape'){e.preventDefault();e.stopImmediatePropagation();if(tradeOverlay)closeTradePopup();else if(!$('modal').hidden){if(selectedSwordSkill&&document.querySelector('.skill-details')){selectedSwordSkill=null;renderSwordSkillWindow($('controlWindowBody'))}else closeModal()}else if(!$('characterOverlay').hidden)closeCharacterWindow();else if(screen==='stages')switchScreen('play');else if(screen==='creator')leaveCreator();else if(screen==='saves')switchScreen('title');return}if(e.code==='Tab'){e.stopImmediatePropagation();return}if(['INPUT','SELECT','TEXTAREA'].includes(active?.tagName)){if(e.code==='Enter'&&active.tagName!=='SELECT'){e.preventDefault();e.stopImmediatePropagation();const confirm=root.querySelector('button.primary:not(:disabled)')||root.querySelector('#createCharacterBtn');confirm?.click()}else if(e.code.startsWith('Arrow'))e.stopImmediatePropagation();return}if(e.code.startsWith('Arrow')){e.preventDefault();e.stopImmediatePropagation();const index=controls.indexOf(active),forward=['ArrowRight','ArrowDown'].includes(e.code);controls[(index+(forward?1:-1)+controls.length)%controls.length].focus();return}if(['Enter','Space'].includes(e.code)){e.preventDefault();e.stopImmediatePropagation();if(e.repeat)return;const target=controls.includes(active)?active:controls[0];target.focus();target.click()}},true);
window.addEventListener('DOMContentLoaded',()=>{$('startBtn').focus()});
